function visibleRows(total, firstVisible, screenRows) {
  const rows = [];
  const last = Math.min(total - 1, firstVisible + screenRows - 1);
  for (let i = firstVisible; i <= last; i++) {
    rows.push(i);
  }
  return rows;
}
console.log(visibleRows(10000, 0, 5).join(','));

